import {getSquadEditor,buildRulesPicker,rulesSummary} from './squad-editor.js';
import {normalizeSelection,footballFormations} from './football-squads.js';
import {createOnlineSession,requestOnlineSeat} from './online-client.js';
import {roomCode,validRoomCode} from './online-protocol.js';
import {footballTeam} from './football-teams.js';
export function onlineInvite(code){const link=new URL(location.href);link.search='?place=pitch&night=1&experience=football&room='+code;link.hash='';return link.href;}
export async function copyOnlineInvite(session,toast){try{await navigator.clipboard.writeText(onlineInvite(session.code));toast?.('邀请链接已复制，发给朋友即可');return true;}catch{toast?.('请复制房间码：'+session.code);return false;}}
export function buildOnlineLobby({getOptions,onEnter,toast,onOpen}){
 const $=id=>document.getElementById(id);let session=null,unsubscribe=null,busy=false,statusMessage='',lastRendered='';
 const picker=buildRulesPicker($('online-rules-picker'),async rules=>{if(!session||busy)return;busy=true;render();try{await session.request({type:'rules',rules});statusMessage='赛制已更新，双方需要重新准备。';}catch(e){statusMessage=e.message;}finally{busy=false;render();}});
 function status(team,room){const seat=room?.seats.find(s=>s.team===team);return !seat?.connected?'等待加入':seat.ready?'已准备':'已连接';}
 function render(){const room=session?.room;for(const button of document.querySelectorAll('[data-match-tab]'))button.disabled=!!session&&button.dataset.matchTab!=='online';$('match-dialog').classList.toggle('online-room-open',!!session);$('match-dialog-title').textContent=session?'好友联机房间':'这一场，迎战谁？';$('match-intro-copy').textContent=session?'先确定赛制，各自排好首发，再准备开球。':'选择对手、赛制与阵容；可以与朋友联机，也可以进行人机比赛。';$('online-lobby-idle').hidden=!!session;$('online-lobby-room').hidden=!session;$('online-create').disabled=$('online-join').disabled=busy;
  $('online-message').textContent=session?.error||statusMessage||'创建房间，或输入朋友的 8 位房间码。';if(!session){const options=getOptions();$('online-fixture-summary').textContent='拜仁 × '+footballTeam(options.opponent).name+' · '+rulesSummary(options.rules);return;}
  const rules=room?.rules||session.rules||getOptions().rules,selection=normalizeSelection(room?.lineups?.[session.team],session.team,session.opponent);$('online-code').textContent=session.code.slice(0,4)+' '+session.code.slice(4);$('online-side').textContent='你控制'+(session.team==='home'?'拜仁':footballTeam(session.opponent).name)+' · '+(session.team==='home'?'房主':'朋友');$('online-home-status').textContent=status('home',room);$('online-away-status').textContent=status('away',room);$('online-away-label').textContent=footballTeam(session.opponent).short;
  $('online-rules-summary').textContent=rulesSummary(rules);$('online-rules-picker').hidden=session.team!=='home';picker.set(rules,busy||room?.started);$('online-lineup-summary').textContent=footballFormations[selection.formation].label+' · '+selection.xi.length+' 名首发';$('online-lineup-edit').disabled=busy||room?.started||session.connection!=='connected';$('online-ready').disabled=session.connection!=='connected'||busy;$('online-ready').textContent='阵容就绪 · 准备进入球场 →';if(!statusMessage&&!session.error)$('online-message').textContent='双方分别确认首发，进入球场并加载完成后开球。';
 }
 function saved(code){try{return JSON.parse(sessionStorage.getItem('arena-online-'+code)||'null');}catch{return null;}}
 async function connect(code){if(busy)return;busy=true;statusMessage=code?'正在加入房间…':'正在创建房间…';render();try{const existing=code?saved(roomCode(code)):null,options=getOptions(),seat=await requestOnlineSeat(code,code?{token:existing?.token}:{opponent:options.opponent,rules:options.rules,selection:normalizeSelection(options.selection)});session?.close();unsubscribe?.();session=createOnlineSession(seat);try{sessionStorage.setItem('arena-online-'+seat.code,JSON.stringify(seat));}catch{}lastRendered='';unsubscribe=session.subscribe(()=>{const key=JSON.stringify([session.connection,session.error,session.room]);if(key!==lastRendered){lastRendered=key;render();}});statusMessage='';render();await session.connect();}catch(e){session?.close();session=null;unsubscribe?.();statusMessage=e.message||'连接失败，请重试';}finally{busy=false;render();}}
 function open(){onOpen?.();$('match-dialog').dataset.panel='online';const panel=$('online-lobby');panel.hidden=false;const code=new URLSearchParams(location.search).get('room');if(code)$('online-room-input').value=roomCode(code);panel.scrollIntoView({block:'nearest',behavior:'smooth'});render();}
 $('match-online').onclick=open;$('online-create').onclick=()=>connect();$('online-join-form').onsubmit=e=>{e.preventDefault();const code=roomCode($('online-room-input').value);if(!validRoomCode(code)){statusMessage='请输入 8 位房间码';render();return;}connect(code);};$('online-copy').onclick=()=>session&&copyOnlineInvite(session,toast);$('online-leave').onclick=()=>{session?.leave();session=null;unsubscribe?.();statusMessage='已离开，可创建新的房间。';render();};$('online-ready').onclick=()=>{if(session?.connection==='connected')onEnter(session);};
 $('online-lineup-edit').onclick=()=>{if(!session||busy)return;getSquadEditor().open({team:session.team,opponent:session.opponent,selection:session.room?.lineups?.[session.team],onSave:async selection=>{const result=await session.request({type:'lineup',selection});statusMessage='首发已保存，请点击准备。';render();return result;}});};
 render();return{open,reset(){session=null;unsubscribe?.();statusMessage='';const url=new URL(location.href);url.searchParams.delete('room');history.replaceState(null,'',url);render();},get session(){return session;}};
}
